// Reads every setting from environment variables and checks them before any API is called.
// Secrets are not copied into the output: the HTTP nodes read the tokens from $env themselves.
const raw = {
  SHOPIFY_STORE_DOMAIN: $env.SHOPIFY_STORE_DOMAIN,
  SHOPIFY_ACCESS_TOKEN: $env.SHOPIFY_ACCESS_TOKEN,
  SHOPIFY_CLIENT_ID: $env.SHOPIFY_CLIENT_ID,
  SHOPIFY_CLIENT_SECRET: $env.SHOPIFY_CLIENT_SECRET,
  SHOPIFY_API_VERSION: $env.SHOPIFY_API_VERSION,
  SHOPIFY_PAGE_SIZE: $env.SHOPIFY_PAGE_SIZE,
  SHOPIFY_VARIANT_QUERY: $env.SHOPIFY_VARIANT_QUERY,
  REORDER_POINT_METAFIELD: $env.REORDER_POINT_METAFIELD,
  DEFAULT_REORDER_POINT: $env.DEFAULT_REORDER_POINT,
  DEFAULT_LEAD_TIME_DAYS: $env.DEFAULT_LEAD_TIME_DAYS,
  SUPPLIERS_JSON: $env.SUPPLIERS_JSON,
  CLICKUP_API_TOKEN: $env.CLICKUP_API_TOKEN,
  CLICKUP_LIST_ID: $env.CLICKUP_LIST_ID,
  CLICKUP_SKU_FIELD_ID: $env.CLICKUP_SKU_FIELD_ID,
  CLICKUP_ASSIGNEE_IDS: $env.CLICKUP_ASSIGNEE_IDS,
  CLICKUP_TAG: $env.CLICKUP_TAG,
  CLICKUP_CLOSED_STATUS: $env.CLICKUP_CLOSED_STATUS,
  CLICKUP_RATE_LIMIT_WAIT_SECONDS: $env.CLICKUP_RATE_LIMIT_WAIT_SECONDS,
};
const get = (name) => (raw[name] === undefined || raw[name] === null ? '' : String(raw[name]).trim());
const problems = [];
const whole = (name, fallback, min, max) => {
  const v = get(name);
  if (v === '') return fallback;
  if (!/^\d+$/.test(v) || Number(v) < min || Number(v) > max) {
    problems.push(`${name} must be a whole number from ${min} to ${max}.`);
    return fallback;
  }
  return Number(v);
};

// Shopify
const domain = get('SHOPIFY_STORE_DOMAIN').toLowerCase().replace(/^https?:\/\//, '').replace(/\/.*$/, '');
if (!domain) problems.push('SHOPIFY_STORE_DOMAIN is missing (for example your-store.myshopify.com).');
else if (!/^[a-z0-9][a-z0-9-]*\.myshopify\.com$/.test(domain)) problems.push('SHOPIFY_STORE_DOMAIN must be the store\'s myshopify.com address, not a custom domain.');
const clientId = get('SHOPIFY_CLIENT_ID');
const clientSecret = get('SHOPIFY_CLIENT_SECRET');
if (Boolean(clientId) !== Boolean(clientSecret)) problems.push('Set both SHOPIFY_CLIENT_ID and SHOPIFY_CLIENT_SECRET, or neither.');
if (!get('SHOPIFY_ACCESS_TOKEN') && !(clientId && clientSecret)) problems.push('Set SHOPIFY_ACCESS_TOKEN, or SHOPIFY_CLIENT_ID and SHOPIFY_CLIENT_SECRET.');
const apiVersion = get('SHOPIFY_API_VERSION') || '2026-10';
if (!/^\d{4}-(01|04|07|10)$/.test(apiVersion)) problems.push('SHOPIFY_API_VERSION must look like 2026-10.');
const metafield = get('REORDER_POINT_METAFIELD') || 'custom.reorder_point';
const mf = /^([A-Za-z0-9_$:-]+)\.([A-Za-z0-9_-]+)$/.exec(metafield);
if (!mf) problems.push('REORDER_POINT_METAFIELD must be namespace.key, for example custom.reorder_point.');

// Suppliers: keys are an exact SKU, a SKU prefix ending in *, a Shopify vendor name, or "default"
let suppliers = {};
if (get('SUPPLIERS_JSON')) {
  try {
    const parsed = JSON.parse(get('SUPPLIERS_JSON'));
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('it must be a JSON object');
    for (const [key, s] of Object.entries(parsed)) {
      if (!s || typeof s !== 'object' || Array.isArray(s)) problems.push(`SUPPLIERS_JSON entry "${key}" must be an object.`);
      else if (s.leadTimeDays !== undefined && !(Number.isInteger(s.leadTimeDays) && s.leadTimeDays >= 0 && s.leadTimeDays <= 365)) problems.push(`SUPPLIERS_JSON entry "${key}" has a leadTimeDays that is not a whole number from 0 to 365.`);
    }
    suppliers = parsed;
  } catch (e) {
    problems.push(`SUPPLIERS_JSON is not valid JSON (${e.message}).`);
  }
}

// ClickUp
if (!get('CLICKUP_API_TOKEN')) problems.push('CLICKUP_API_TOKEN is missing.');
const listId = get('CLICKUP_LIST_ID');
if (!/^\d+$/.test(listId)) problems.push('CLICKUP_LIST_ID is missing or not a number. It is the number after /li/ in the list URL.');
const assigneeText = get('CLICKUP_ASSIGNEE_IDS');
const assignees = assigneeText ? assigneeText.split(',').map((s) => s.trim()).filter(Boolean) : [];
if (assignees.some((a) => !/^\d+$/.test(a))) problems.push('CLICKUP_ASSIGNEE_IDS must be ClickUp user IDs (numbers), separated by commas.');
const skuFieldId = get('CLICKUP_SKU_FIELD_ID');
if (skuFieldId && !/^[0-9a-f-]{36}$/i.test(skuFieldId)) problems.push('CLICKUP_SKU_FIELD_ID must be a custom field ID like 0a1b2c3d-1234-5678-9abc-0123456789ab.');
const tag = get('CLICKUP_TAG') || 'low-stock';

return [{
  json: {
    ok: problems.length === 0,
    problems,
    trigger: $('Daily Schedule').isExecuted ? 'scheduled' : 'run now',
    startedAt: new Date().toISOString(),
    shop: {
      domain,
      // The store URL is built in this one place, so the tests can point it at a mock.
      baseUrl: 'https://{shop}'.replace('{shop}', domain),
      apiVersion,
      useClientCredentials: Boolean(clientId && clientSecret),
      pageSize: whole('SHOPIFY_PAGE_SIZE', 100, 1, 200),
      // Written like Shopify's own example for this filter (product_status:ACTIVE,DRAFT)
      variantQuery: get('SHOPIFY_VARIANT_QUERY') || 'product_status:ACTIVE',
      metafieldNamespace: mf ? mf[1] : 'custom',
      metafieldKey: mf ? mf[2] : 'reorder_point',
    },
    defaults: {
      reorderPoint: whole('DEFAULT_REORDER_POINT', 5, 0, 1000000),
      leadTimeDays: whole('DEFAULT_LEAD_TIME_DAYS', 14, 0, 365),
    },
    suppliers,
    clickup: {
      listId,
      skuFieldId,
      assignees: assignees.map(Number),
      tag: tag.toLowerCase() === 'none' ? '' : tag,
      closedStatus: get('CLICKUP_CLOSED_STATUS') || 'complete',
      rateLimitWaitSeconds: whole('CLICKUP_RATE_LIMIT_WAIT_SECONDS', 60, 1, 600),
      rateLimitRetries: 3,
    },
  },
}];

// Collects the open tasks in the reorder list and finds the SKU of each one:
// the SKU custom field when it is set, otherwise the "Reorder SKU: ..." task name.
const settings = $('Load Settings').first().json;
const fieldId = settings.clickup.skuFieldId;
const pages = $input.all();
const bySku = {};
let openCount = 0;
let otherTasks = 0;
for (const page of pages) {
  for (const t of page.json.tasks || []) {
    const type = String((t.status && t.status.type) || '').toLowerCase();
    if (type === 'closed' || type === 'done') continue;
    openCount += 1;
    let sku = '';
    if (fieldId) {
      const field = (t.custom_fields || []).find((f) => f.id === fieldId);
      if (field && field.value !== undefined && field.value !== null) sku = String(field.value).trim();
    }
    if (!sku) {
      const m = /^Reorder\s+(.+?):\s/i.exec(t.name || '');
      if (m) sku = m[1].trim();
    }
    if (!sku) { otherTasks += 1; continue; }
    const stock = /On hand:\s*(-?\d+)/i.exec(t.text_content || t.description || '');
    const key = sku.toUpperCase();
    (bySku[key] = bySku[key] || []).push({
      id: t.id,
      url: t.url,
      sku,
      priority: t.priority && t.priority.id ? Number(t.priority.id) : null,
      created: Number(t.date_created || 0),
      stockInDescription: stock ? Number(stock[1]) : null,
    });
  }
}
// The oldest task for a SKU is the one that is kept up to date
for (const list of Object.values(bySku)) list.sort((a, b) => a.created - b.created || String(a.id).localeCompare(String(b.id)));
return [{ json: { bySku, skus: Object.keys(bySku), openCount, otherTasks, pagesRead: pages.length } }];

// Builds the GraphQL request for the next page of variants. The scan loop comes back here after every page.
const shop = $('Load Settings').first().json.shop;
const s = $json;
const state = { cursor: s.cursor || null, pages: s.pages || 0, readRuns: s.readRuns || 0, throttleWaits: s.throttleWaits || 0 };
const query = `query LowStockScan($first: Int!, $after: String, $query: String, $ns: String!, $key: String!) {
  productVariants(first: $first, after: $after, query: $query, sortKey: ID) {
    nodes {
      id
      sku
      title
      inventoryQuantity
      inventoryItem { tracked }
      product { id title vendor }
      reorderPoint: metafield(namespace: $ns, key: $key) { value }
    }
    pageInfo { hasNextPage endCursor }
  }
}`;
const variables = { first: shop.pageSize, after: state.cursor, query: shop.variantQuery, ns: shop.metafieldNamespace, key: shop.metafieldKey };
return [{ json: { ...state, request: { query, variables } } }];

// Reads one page of variants and decides what happens next: done, next page, wait, or fail.
// Each run outputs only its own page, so a big catalog is not copied through every loop pass.
const settings = $('Load Settings').first().json;
const openSkus = new Set($('Index Open Tasks').first().json.skus);
const state = $('Next Page').first().json;   // the request this answer belongs to
const res = $json;
const MAX_THROTTLE_WAITS = 5;
const MAX_WAIT_SECONDS = 60;
const MAX_PAGES = 1000;

const next = {
  cursor: state.cursor || null,
  pages: state.pages || 0,
  readRuns: (state.readRuns || 0) + 1,
  throttleWaits: state.throttleWaits || 0,
  waitSeconds: 0,
  route: 'next',
  records: [],
  counts: { variants: 0, untracked: 0, noSku: 0, noStock: 0 },
  notes: [],
};
const fail = (message) => [{ json: { ...next, route: 'fail', failure: message } }];
const cost = res.extensions && res.extensions.cost;
const secondsToRefill = (needed) => {
  const t = cost && cost.throttleStatus;
  if (!t || !(Number(t.restoreRate) > 0) || typeof needed !== 'number') return 0;
  return Math.ceil(Math.max(0, needed - Number(t.currentlyAvailable)) / Number(t.restoreRate));
};
const waitAndRetry = (seconds, reason) => {
  next.throttleWaits += 1;
  if (next.throttleWaits > MAX_THROTTLE_WAITS) {
    return fail(`Shopify kept throttling the stock scan (${reason}) after ${MAX_THROTTLE_WAITS} waits. Nothing was changed in ClickUp.`);
  }
  next.waitSeconds = Math.min(MAX_WAIT_SECONDS, Math.max(1, seconds));
  next.route = 'wait';
  return [{ json: next }];
};

// 1. HTTP errors. The node has already retried 3 times.
if (res.error && !res.data) {
  const status = Number(res.error.status || res.error.statusCode || (res.error.response && res.error.response.status) || 0);
  if (status === 429) return waitAndRetry(2 ** (next.throttleWaits + 1), 'HTTP 429');
  // n8n puts the status and the raw body in the message, like 503 - "{\"errors\":\"...\"}"
  let detail = String(res.error.message || 'no details');
  const m = /^\d{3} - ("[\s\S]*")$/.exec(detail);
  if (m) {
    try {
      const body = JSON.parse(m[1]);
      try {
        const j = JSON.parse(body);
        detail = typeof j.errors === 'string' ? j.errors : JSON.stringify(j.errors || j).slice(0, 300);
      } catch (x) {
        detail = String(body).slice(0, 300);
      }
    } catch (x) { /* keep the message as it is */ }
  }
  return fail(`The Shopify stock scan failed${status ? ' with HTTP ' + status : ''} (${detail}). Nothing was changed in ClickUp.`);
}
// 2. GraphQL errors come back with HTTP 200
const errors = Array.isArray(res.errors) ? res.errors : res.errors ? [{ message: String(res.errors) }] : [];
if (errors.some((e) => e && e.extensions && e.extensions.code === 'THROTTLED')) {
  const needed = cost && typeof cost.requestedQueryCost === 'number' ? cost.requestedQueryCost : null;
  return waitAndRetry(secondsToRefill(needed) || 2 ** (next.throttleWaits + 1), 'THROTTLED');
}
if (errors.length) {
  const text = errors.map((e) => (e.extensions && e.extensions.code ? e.extensions.code + ': ' : '') + e.message).join('; ').replace(/[.\s]+$/, '');
  return fail(`Shopify returned an error for the stock scan: ${text}. Nothing was changed in ClickUp.`);
}
const conn = res.data && res.data.productVariants;
if (!conn || !Array.isArray(conn.nodes)) return fail('Shopify answered without a productVariants list. Nothing was changed in ClickUp.');

// 3. A good page
next.throttleWaits = 0;
next.pages += 1;
const def = settings.defaults.reorderPoint;
const gidNumber = (gid) => String(gid || '').split('/').pop();
for (const v of conn.nodes) {
  next.counts.variants += 1;
  const sku = String(v.sku || '').trim();
  if (!sku) { next.counts.noSku += 1; continue; }
  if (!v.inventoryItem || v.inventoryItem.tracked !== true) { next.counts.untracked += 1; continue; }
  if (typeof v.inventoryQuantity !== 'number') { next.counts.noStock += 1; continue; }
  let reorderPoint = def;
  let source = 'default';
  const raw = v.reorderPoint && v.reorderPoint.value !== undefined && v.reorderPoint.value !== null ? String(v.reorderPoint.value).trim() : '';
  if (raw !== '') {
    if (/^\d+$/.test(raw)) { reorderPoint = Number(raw); source = 'metafield'; }
    else next.notes.push(`${sku}: the reorder point metafield is "${raw.slice(0, 30)}", which is not a whole number, so the default of ${def} was used.`);
  }
  const record = { sku, qty: v.inventoryQuantity, reorderPoint };
  // Full details only for variants that are low or have an open task. The rest only count toward SKU totals.
  if (record.qty <= reorderPoint || openSkus.has(sku.toUpperCase())) {
    Object.assign(record, {
      source,
      variantId: gidNumber(v.id),
      productId: gidNumber(v.product && v.product.id),
      product: (v.product && v.product.title) || '',
      variant: v.title || '',
      vendor: (v.product && v.product.vendor) || '',
    });
  }
  next.records.push(record);
}
next.cursor = (conn.pageInfo && conn.pageInfo.endCursor) || null;
if (!(conn.pageInfo && conn.pageInfo.hasNextPage) || !next.cursor) {
  next.route = 'done';
  return [{ json: next }];
}
if (next.pages >= MAX_PAGES) return fail(`The stock scan stopped after ${MAX_PAGES} pages. Narrow SHOPIFY_VARIANT_QUERY or raise SHOPIFY_PAGE_SIZE.`);
// Shopify refills its query budget every second. If the next page would not fit, wait first.
const pause = secondsToRefill(cost && cost.requestedQueryCost);
if (pause > 0) {
  next.waitSeconds = Math.min(MAX_WAIT_SECONDS, pause);
  next.route = 'wait';
}
return [{ json: next }];

// Compares Shopify stock with the open reorder tasks and plans the ClickUp changes.
const settings = $('Load Settings').first().json;
const open = $('Index Open Tasks').first().json;
const scan = $json;
const store = $getWorkflowStaticData('global');
store.reported = store.reported || {};   // task ID -> the stock number the team was last told about
const DAY = 24 * 60 * 60 * 1000;
const now = Date.now();
const PRIORITY = { 1: 'urgent', 2: 'high', 3: 'normal', 4: 'low' };

// Every page the scan read (a throttled attempt has no records)
const counts = { variants: 0, untracked: 0, noSku: 0, noStock: 0 };
const needsLook = [];
const groups = new Map();
for (let run = 0; run < scan.readRuns; run++) {
  for (const item of $('Read Page').all(0, run)) {
    const page = item.json;
    for (const k of Object.keys(counts)) counts[k] += (page.counts && page.counts[k]) || 0;
    needsLook.push(...(page.notes || []));
    for (const r of page.records || []) {
      // Shopify allows one SKU on several variants. Their stock is added up.
      const key = r.sku.toUpperCase();
      const g = groups.get(key) || { key, qty: 0, reorderPoint: 0, variants: 0, info: null };
      g.qty += r.qty;
      g.reorderPoint = Math.max(g.reorderPoint, r.reorderPoint);
      g.variants += 1;
      if (!g.info && r.variantId) g.info = r;
      groups.set(key, g);
    }
  }
}

const supplierFor = (sku, vendor) => {
  const s = settings.suppliers;
  if (s[sku]) return s[sku];
  const prefix = Object.keys(s)
    .filter((k) => k.endsWith('*') && sku.toUpperCase().startsWith(k.slice(0, -1).toUpperCase()))
    .sort((a, b) => b.length - a.length)[0];
  if (prefix) return s[prefix];
  if (vendor && s[vendor]) return s[vendor];
  return s.default || null;
};
// 1 urgent: out of stock. 2 high: at or below half the reorder point. 3 normal: the rest.
const severity = (qty, rop) => (qty <= 0 ? 1 : qty <= Math.floor(rop / 2) ? 2 : 3);
const titleOf = (i) => i.product + (i.variant && i.variant !== 'Default Title' ? ` (${i.variant})` : '');
const handle = settings.shop.domain.replace(/\.myshopify\.com$/, '');

const actions = [];
const stillLow = [];
const seen = new Set();
let lowCount = 0;
let restockedCount = 0;

for (const g of groups.values()) {
  if (!g.info) continue;   // not low and no open task
  const i = g.info;
  const title = titleOf(i);
  const low = g.qty <= g.reorderPoint;
  const tasks = open.bySku[g.key] || [];
  const task = tasks[0];
  seen.add(g.key);
  if (low) lowCount += 1;
  if (g.variants > 1) needsLook.push(`${i.sku} is used on ${g.variants} variants. Their stock was added up: ${g.qty} on hand.`);
  if (tasks.length > 1) needsLook.push(`${i.sku} has ${tasks.length} open reorder tasks. The oldest one is kept up to date. Please close the others: ${tasks.slice(1).map((t) => `<${t.url}|${t.id}>`).join(', ')}`);
  const base = { sku: i.sku, listId: settings.clickup.listId, taskId: task ? task.id : null, taskUrl: task ? task.url : null, stepIndex: 0, rateLimitWaits: 0 };
  const info = { title, qty: g.qty, reorderPoint: g.reorderPoint };

  if (low && !task) {
    const supplier = supplierFor(i.sku, i.vendor);
    const leadDays = supplier && Number.isInteger(supplier.leadTimeDays) ? supplier.leadTimeDays : settings.defaults.leadTimeDays;
    const due = now + leadDays * DAY;
    const p = severity(g.qty, g.reorderPoint);
    const supplierText = supplier && (supplier.name || supplier.email) ? [supplier.name, supplier.email].filter(Boolean).join(', ') : 'not set (add it to SUPPLIERS_JSON)';
    const description = [
      'Stock is at or below the reorder point in Shopify.',
      '',
      `SKU: ${i.sku}`,
      `Product: ${title}`,
      `On hand: ${g.qty}`,
      `Reorder point: ${g.reorderPoint}${i.source === 'metafield' ? '' : ' (store default)'}`,
      `Supplier: ${supplierText}`,
      `Lead time: ${leadDays} days. The due date is when new stock should arrive if it is ordered today.`,
      `Shopify: https://admin.shopify.com/store/${handle}/products/${i.productId}/variants/${i.variantId}`,
      '',
      'Opened by the daily low stock check. It adds a comment when stock drops further and closes this task when stock is back above the reorder point.',
    ].join('\n');
    const body = { name: `Reorder ${i.sku}: ${title}`, description, priority: p, due_date: due, due_date_time: false, notify_all: false };
    if (settings.clickup.assignees.length) body.assignees = settings.clickup.assignees;
    if (settings.clickup.tag) body.tags = [settings.clickup.tag];
    if (settings.clickup.skuFieldId) body.custom_fields = [{ id: settings.clickup.skuFieldId, value: i.sku }];
    // With a SKU field, ClickUp is asked once more right before the create (see ClickUp: Find SKU Task)
    const steps = settings.clickup.skuFieldId ? [{ kind: 'check' }, { kind: 'create', body }] : [{ kind: 'create', body }];
    actions.push({
      ...base, actionId: `${i.sku}:new`, purpose: 'new', steps,
      info: { ...info, priorityName: PRIORITY[p], supplierName: supplier && supplier.name ? supplier.name : 'no supplier set', dueText: DateTime.fromMillis(due).toFormat('LLL d'), leadDays },
    });
    continue;
  }
  if (!task) continue;

  if (!low) {
    // Back in stock: close first, then explain. A failed close is retried on the next run; the comment is never doubled.
    restockedCount += 1;
    const text = `Back in stock: ${g.qty} on hand, above the reorder point of ${g.reorderPoint}. Closed automatically by the low stock check.`;
    actions.push({
      ...base, actionId: `${i.sku}:restock`, purpose: 'restock',
      steps: [{ kind: 'update', body: { status: settings.clickup.closedStatus } }, { kind: 'comment', body: { comment_text: text, notify_all: false } }],
      info,
    });
    continue;
  }

  // Still low and a task is open: comment only when stock fell below the number the team last saw
  const known = store.reported[task.id];
  const previous = known && typeof known.stock === 'number' ? known.stock : task.stockInDescription;
  const p = severity(g.qty, g.reorderPoint);
  const raise = task.priority === null || task.priority > p;   // never lowers a priority someone set
  const steps = [];
  if (typeof previous !== 'number') {
    store.reported[task.id] = { sku: i.sku, stock: g.qty, at: now };   // a task made by hand: start tracking from today
  } else if (g.qty < previous) {
    let text = `Stock dropped from ${previous} to ${g.qty} on hand (reorder point ${g.reorderPoint}).`;
    if (g.qty <= 0) text += ' It is now out of stock.';
    if (raise) text += ` Priority raised to ${PRIORITY[p]}.`;
    steps.push({ kind: 'comment', body: { comment_text: text, notify_all: false } });
  }
  if (raise) steps.push({ kind: 'update', body: { priority: p } });
  if (!steps.length) {
    stillLow.push({ sku: i.sku, title, qty: g.qty, reorderPoint: g.reorderPoint, taskUrl: task.url });
    continue;
  }
  const purpose = steps[0].kind === 'comment' ? 'drop' : 'raise';
  actions.push({ ...base, actionId: `${i.sku}:${purpose}`, purpose, steps, info: { ...info, previous, priorityName: PRIORITY[p], raise } });
}

// Open tasks whose SKU the scan did not find
for (const [key, tasks] of Object.entries(open.bySku)) {
  if (!seen.has(key)) needsLook.push(`${tasks[0].sku} has an open reorder task, but no tracked Shopify variant in this scan has that SKU. <${tasks[0].url}|Open task>`);
}
// Forget tasks that are no longer open
const openIds = new Set(Object.values(open.bySku).flat().map((t) => String(t.id)));
for (const id of Object.keys(store.reported)) if (!openIds.has(id)) delete store.reported[id];

return [{
  json: {
    actions,
    summary: { trigger: settings.trigger, startedAt: settings.startedAt, pages: scan.pages, counts, lowCount, restockedCount, stillLow, needsLook },
  },
}];

// Picks the next ClickUp call for this change. After a 429 wait, the same step comes back here.
const a = { ...$json };
if (a.error) {
  a.rateLimitWaits = (a.rateLimitWaits || 0) + 1;
  delete a.error;
}
const step = a.steps[a.stepIndex];
a.kind = step.kind;
a.body = step.body;
return [{ json: a }];

// Records the result of one ClickUp call and remembers the stock number the team was told about.
const a = JSON.parse(JSON.stringify($('Prepare Step').first().json));
const store = $getWorkflowStaticData('global');
store.reported = store.reported || {};
const failed = $json.error !== undefined && $json.actionId === a.actionId;
// n8n puts the status and the raw body in the message, like 500 - "{\"err\":\"...\",\"ECODE\":\"...\"}"
const readable = (e) => {
  const msg = String(e.message || 'no details');
  const m = /^\d{3} - ("[\s\S]*")$/.exec(msg);
  if (!m) return msg;
  try {
    const body = JSON.parse(m[1]);
    try {
      const j = JSON.parse(body);
      return j.err ? j.err + (j.ECODE ? ' (' + j.ECODE + ')' : '') : JSON.stringify(j).slice(0, 300);
    } catch (x) {
      return String(body).slice(0, 300);
    }
  } catch (x) {
    return msg;
  }
};
a.stepsDone = a.stepsDone || [];
const badAnswer = !failed && ((a.kind === 'create' && !$json.id) || (a.kind === 'check' && !Array.isArray($json.tasks)));
if (failed || badAnswer) {
  // A failed check also stops the create: without the check a duplicate could slip through. The next run tries again.
  const e = $json.error || {};
  const code = e.status || e.statusCode || (e.response && e.response.status);
  a.ok = false;
  a.failedStep = a.kind;
  // For a 429 n8n only says "Try spacing your requests out...", which is about n8n batching, so it is replaced
  const detail = Number(code) === 429 ? `the rate limit was still reached after ${a.rateLimitWaits || 0} waits` : readable(e);
  a.error = failed ? (code ? 'HTTP ' + code + ', ' : '') + detail : a.kind === 'create' ? 'ClickUp did not return a task ID' : 'ClickUp did not return a task list';
  a.route = 'finished';
} else if (a.kind === 'check') {
  // Only an open task whose SKU field is exactly this SKU counts
  const fieldId = $('Load Settings').first().json.clickup.skuFieldId;
  const want = String(a.sku).trim().toUpperCase();
  const found = $json.tasks.filter((t) => {
    const type = String((t.status && t.status.type) || '').toLowerCase();
    if (type === 'closed' || type === 'done') return false;
    const f = (t.custom_fields || []).find((x) => x.id === fieldId);
    return Boolean(f) && f.value !== undefined && f.value !== null && String(f.value).trim().toUpperCase() === want;
  });
  a.stepsDone.push('check');
  if (found.length) {
    a.ok = true;
    a.alreadyOpen = true;
    a.taskId = found[0].id;
    a.taskUrl = found[0].url;
    a.route = 'finished';
  } else {
    a.stepIndex += 1;
    a.route = 'more';
  }
} else {
  if (a.kind === 'create') {
    a.taskId = $json.id;
    a.taskUrl = $json.url;
  }
  a.stepsDone.push(a.kind);
  if (a.purpose === 'new' && a.kind === 'create') store.reported[a.taskId] = { sku: a.sku, stock: a.info.qty, at: Date.now() };
  if (a.purpose === 'drop' && a.kind === 'comment') store.reported[a.taskId] = { sku: a.sku, stock: a.info.qty, at: Date.now() };
  if (a.purpose === 'restock' && a.kind === 'update') delete store.reported[a.taskId];
  a.stepIndex += 1;
  if (a.stepIndex < a.steps.length) a.route = 'more';
  else {
    a.ok = true;
    a.route = 'finished';
  }
}
delete a.body;
delete a.kind;
return [{ json: a }];

// Writes the Slack digest for this run.
const plan = $('Plan Changes').first().json;
const s = plan.summary;
const results = $('Loop: ClickUp Changes').isExecuted ? $input.all().map((i) => i.json) : [];
const did = (r, kind) => (r.stepsDone || []).includes(kind);
const link = (url) => (url ? ` <${url}|Open task>` : '');
const cap = (w) => w.charAt(0).toUpperCase() + w.slice(1);
const MAX_LINES = 25;
const blocks = [];
const block = (title, lines) => {
  if (!lines.length) return;
  const shown = lines.slice(0, MAX_LINES).map((l) => `• ${l}`);
  if (lines.length > MAX_LINES) shown.push(`and ${lines.length - MAX_LINES} more`);
  blocks.push(`*${title} (${lines.length})*\n${shown.join('\n')}`);
};

block('New reorder tasks', results.filter((r) => r.purpose === 'new' && did(r, 'create')).map((r) =>
  `${r.sku} ${r.info.title}: ${r.info.qty} on hand, reorder point ${r.info.reorderPoint}. ${cap(r.info.priorityName)} priority, ${r.info.supplierName}, due ${r.info.dueText}.${link(r.taskUrl)}`));

block('Updated', results.filter((r) => (r.purpose === 'drop' && did(r, 'comment')) || (r.purpose === 'raise' && did(r, 'update'))).map((r) => {
  const raised = did(r, 'update') ? `priority raised to ${r.info.priorityName}` : '';
  if (r.purpose === 'raise') return `${r.sku} ${r.info.title}: ${raised} (${r.info.qty} on hand, reorder point ${r.info.reorderPoint}).${link(r.taskUrl)}`;
  const parts = [`dropped from ${r.info.previous} to ${r.info.qty} on hand`];
  if (r.info.qty <= 0) parts.push('now out of stock');
  if (raised) parts.push(raised);
  return `${r.sku} ${r.info.title}: ${parts.join(', ')} (reorder point ${r.info.reorderPoint}).${link(r.taskUrl)}`;
}));

block('Restocked and closed', results.filter((r) => r.purpose === 'restock' && did(r, 'update')).map((r) =>
  `${r.sku} ${r.info.title}: ${r.info.qty} on hand, above the reorder point of ${r.info.reorderPoint}.${link(r.taskUrl)}`));

block('Still low, no change', s.stillLow.map((x) => `${x.sku} ${x.title}: ${x.qty} on hand, reorder point ${x.reorderPoint}.${link(x.taskUrl)}`));
// An open task for the SKU appeared after this run read the list (a second run, or a person). No second task was made.
const appeared = results.filter((r) => r.alreadyOpen).map((r) =>
  `${r.sku} is low (${r.info.qty} on hand, reorder point ${r.info.reorderPoint}), but an open reorder task for it was made while this run was going, so no second task was created.${link(r.taskUrl)}`);
block('Needs a look', [...s.needsLook, ...appeared]);

const failures = results.filter((r) => !r.ok).map((r) => {
  if (r.purpose === 'restock' && r.failedStep === 'comment') return `${r.sku}: the task was closed, but the comment could not be added (${r.error}).`;
  const what = { check: 'check ClickUp for an open task, so no task was created', create: 'create the reorder task', comment: 'add the stock comment', update: r.purpose === 'restock' ? 'close the task' : 'raise the priority' }[r.failedStep];
  return `${r.sku}: could not ${what} (${r.error}). It is tried again on the next run.`;
});
block('Could not update ClickUp', failures);

const c = s.counts;
const skipped = [];
if (c.untracked) skipped.push(`${c.untracked} not tracked`);
if (c.noSku) skipped.push(`${c.noSku} without a SKU`);
if (c.noStock) skipped.push(`${c.noStock} without a stock number`);
const head = [
  `*Low stock check*, ${DateTime.fromISO(s.startedAt).toFormat('LLL d, yyyy h:mm a')} (${s.trigger})`,
  `Checked ${c.variants} variants on ${s.pages} page${s.pages === 1 ? '' : 's'}: ${s.lowCount} low, ${s.restockedCount} back in stock.` + (skipped.length ? ` Skipped ${skipped.join(', ')}.` : ''),
];
if (!blocks.length) head.push('Nothing is low. No changes in ClickUp.');
return [{ json: { text: [head.join('\n'), ...blocks].join('\n\n'), failedCount: failures.length, failures } }];
